WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_DINAMICAS' AND v.numero=1),d(t,o) AS (VALUES('DATOS DE PRUEBA',1),('PRUEBAS DINÁMICAS',2),('TIRADORES DE ALARMA',3),('FUNCIONALIDAD DEL HOMBRE MUERTO',4),('FRENO DE RETENCIÓN',5),('FRENO DE ESTACIONAMIENTO',6),('FRENO DE SERVICIO COMBINADO (Vía Principal)',7),('FRENO DE EMERGENCIA (Vía Principal)',8),('FRENO NEUMÁTICO (Vía Principal)',9),('OBSERVACIONES:',10),('PERSONAL',11)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_DINAMICAS' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),d(t,c,e,ty,o,cf) AS (VALUES('DATOS DE PRUEBA','tren','TREN N°','texto',1,'{}'),('DATOS DE PRUEBA','fecha','Fecha de prueba:','fecha',2,'{}'),('PRUEBAS DINÁMICAS','velocidades','VELOCIDADES','tabla',1,'{"columnas":[{"codigo":"prueba","etiqueta":"PRUEBA"},{"codigo":"criterio","etiqueta":"CRITERIO"},{"codigo":"ma1","etiqueta":"MA1 √/X"},{"codigo":"ma2","etiqueta":"MA2 √/X"}],"filasIniciales":[{"prueba":"VELOCIDAD TÚNEL DE LAVADO","criterio":"5 Km/h"},{"prueba":"VELOCIDAD DE MANIOBRA","criterio":"12 Km/h"},{"prueba":"VELOCIDAD DE MARCHA ATRÁS","criterio":"12 Km/h"},{"prueba":"RELÉ DE VELOCIDAD 0"},{"prueba":"ANULACIÓN AUTORIZACIÓN DE TRACCIÓN"}]}'),('TIRADORES DE ALARMA','tiradores','TIRADORES DE ALARMA','tabla',1,'{"columnas":[{"codigo":"control","etiqueta":"CONTROL"},{"codigo":"resultado","etiqueta":"RESULTADO"}],"filasIniciales":[{"control":"Antes de recorrer 45 m","criterio":"Se aplica freno emergencia; petición comunicación"},{"control":"Después de recorrer 45 m","criterio":"No freno emergencia; petición comunicación"}]}'),('FUNCIONALIDAD DEL HOMBRE MUERTO','hombre_muerto','FUNCIONALIDAD DEL HOMBRE MUERTO','tabla',1,'{"columnas":[{"codigo":"control","etiqueta":"CONTROL"},{"codigo":"resultado","etiqueta":"RESULTADO"}],"filasIniciales":[{"control":"A los 27 segundos"},{"control":"A los 30 segundos"},{"control":"Soltar empuñadura; transcurridos 5 segundos"}]}'),('FRENO DE RETENCIÓN','retencion','FRENO DE RETENCIÓN','tabla',1,'{"columnas":[{"codigo":"control","etiqueta":"CONTROL"},{"codigo":"resultado","etiqueta":"RESULTADO"}],"filasIniciales":[{"control":"Tren detenido"},{"control":"Inicio de tracción"}]}'),('FRENO DE ESTACIONAMIENTO','estacionamiento','FRENO DE ESTACIONAMIENTO','tabla',1,'{"columnas":[{"codigo":"control","etiqueta":"CONTROL"},{"codigo":"resultado","etiqueta":"RESULTADO"}],"filasIniciales":[{"control":"Aflojar freno estacionamiento","criterio":"7,7 ± 0,2 bar"},{"control":"Llave de gobierno en 0","criterio":"Presiones DDU 0"}]}'),('FRENO DE SERVICIO COMBINADO (Vía Principal)','servicio_combinado','FRENO DE SERVICIO COMBINADO','tabla',1,'{"columnas":[{"codigo":"sentido","etiqueta":"SENTIDO"},{"codigo":"deceleracion","etiqueta":"DECELERACIÓN (m/s2)"}],"filasIniciales":[{"sentido":"Ida","criterio":"1,2 m/s2 +/-10% (1,08 a 1,32)"},{"sentido":"Vuelta","criterio":"1,2 m/s2 +/-10% (1,08 a 1,32)"}]}'),('FRENO DE EMERGENCIA (Vía Principal)','emergencia','FRENO DE EMERGENCIA','tabla',1,'{"columnas":[{"codigo":"sentido","etiqueta":"SENTIDO"},{"codigo":"deceleracion","etiqueta":"DECELERACIÓN (m/s2)"}],"filasIniciales":[{"sentido":"Ida","criterio":"1,4 m/s2 +/-10% (1,26 a 1,54)"},{"sentido":"Vuelta","criterio":"1,4 m/s2 +/-10% (1,26 a 1,54)"}]}'),('FRENO NEUMÁTICO (Vía Principal)','neumatico','FRENO NEUMÁTICO','tabla',1,'{"columnas":[{"codigo":"sentido","etiqueta":"SENTIDO"},{"codigo":"deceleracion","etiqueta":"DECELERACIÓN (m/s2)"}],"filasIniciales":[{"sentido":"Ida","criterio":"1,2 m/s2 +/-10% (1,08 a 1,32)"},{"sentido":"Vuelta","criterio":"1,2 m/s2 +/-10% (1,08 a 1,32)"}]}'),('OBSERVACIONES:','observaciones','OBSERVACIONES:','texto',1,'{"multilinea":true}'),('PERSONAL','personal','PERSONAL','tabla',1,'{"columnas":[{"codigo":"cargo","etiqueta":"CARGO"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"cargo":"TÉCNICO:"},{"cargo":"TÉCNICO:"},{"cargo":"SUPERVISOR:"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf::jsonb FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
